<?php
error_reporting(E_ALL);
if(!class_exists('adriangibbons\phpFITFileAnalysis')) {
    require __DIR__ . '/../src/phpFITFileAnalysis.php';
}
require_once __DIR__ . '/FitFileBuilder.php';

/**
 * Messages, fields and enumerated types come from Garmin's FIT SDK profile (src/Profile.php,
 * generated by bin/generate-profile.php), so everything the SDK defines is decoded -- the library
 * used to know 22 of its messages and drop the rest.
 */
class ProfileTest extends \PHPUnit\Framework\TestCase
{
    use FitFileBuilder;

    private const SESSION = 18;
    private const TIME_IN_ZONE = 216;
    private const SET = 225;
    private const SPLIT = 312;
    private const DEVICE_INFO = 23;
    private const UINT8 = 0x02;
    private const UINT16 = 0x84;
    private const SINT32 = 0x85;
    private const UINT32 = 0x86;

    private function parse($bytes, array $options = [])
    {
        return new adriangibbons\phpFITFileAnalysis($this->fitFile($bytes), $options + ['input_is_data' => true, 'units' => 'raw']);
    }

    public function testTheProfileIsThePinnedSdkVersion()
    {
        $this->assertSame(trim(file_get_contents(__DIR__ . '/../bin/fit-sdk-version.txt')), adriangibbons\Profile::VERSION);
    }

    public function testSpotChecksAgainstTheSdk()
    {
        $messages = adriangibbons\Profile::MESSAGES;

        $this->assertSame('enhanced_speed', $messages[20]['fields'][73]['name']);
        $this->assertSame(1000, $messages[20]['fields'][73]['scale']);
        $this->assertSame([[73, 16, 1000, 0]], $messages[20]['fields'][6]['components']);
        $this->assertSame('enhanced_avg_speed', $messages[18]['fields'][124]['name']);
        $this->assertSame('time_in_zone', $messages[216]['name']);
        $this->assertSame('fr970', adriangibbons\Profile::TYPES['garmin_product'][4565]);
    }

    public function testSessionFieldsCurrentDevicesWriteAreDecoded()
    {
        // enhanced_avg_speed (124, uint32 /1000), total_anaerobic_training_effect (137, /10),
        // training_load_peak (168, sint32 /65536).
        $session = $this->parse(
            $this->definition(0, self::SESSION, [[253, 4, self::UINT32], [124, 4, self::UINT32], [137, 1, self::UINT8], [168, 4, self::SINT32]])
            . $this->data(0, pack('VVCV', 1000, 3250, 21, (int) (152.5 * 65536)))
        )->data_mesgs['session'];

        $this->assertEqualsWithDelta(3.25, $session['enhanced_avg_speed'], 1e-9);
        $this->assertEqualsWithDelta(2.1, $session['total_anaerobic_training_effect'], 1e-9);
        $this->assertEqualsWithDelta(152.5, $session['training_load_peak'], 1e-9);
    }

    public function testTimeInZoneIsDecoded()
    {
        $tiz = $this->parse(
            $this->definition(0, self::TIME_IN_ZONE, [[253, 4, self::UINT32], [0, 2, self::UINT16], [2, 12, self::UINT32], [6, 2, self::UINT8], [11, 1, self::UINT8]])
            . $this->data(0, pack('VvVVVCCC', 1000, self::SESSION, 600000, 1200000, 300000, 150, 170, 188))
        )->data_mesgs['time_in_zone'];

        $this->assertSame(self::SESSION, $tiz['reference_mesg']);
        $this->assertSame([600, 1200, 300], $tiz['time_in_hr_zone']);
        $this->assertSame([150, 170], $tiz['hr_zone_high_boundary']);
        $this->assertSame(188, $tiz['max_heart_rate']);
    }

    public function testSplitsAndStrengthSetsAreDecoded()
    {
        $pFFA = $this->parse(
            $this->definition(0, self::SPLIT, [[0, 1, self::UINT8], [1, 4, self::UINT32], [3, 4, self::UINT32]])
            . $this->data(0, pack('CVV', 3, 300000, 100000))
            . $this->data(0, pack('CVV', 4, 60000, 0xFFFFFFFF))
            . $this->definition(1, self::SET, [[254, 4, self::UINT32], [3, 2, self::UINT16], [4, 2, self::UINT16]])
            . $this->data(1, pack('Vvv', 1000, 12, 60 * 16))
        );

        $this->assertSame([300, 60], $pFFA->data_mesgs['split']['total_elapsed_time']);
        $this->assertSame([1000, null], $pFFA->data_mesgs['split']['total_distance']);
        $this->assertSame(12, $pFFA->data_mesgs['set']['repetitions']);
        $this->assertEqualsWithDelta(60.0, $pFFA->data_mesgs['set']['weight'], 1e-9);
    }

    public function testEnumNamesFallBackToTheSdk()
    {
        $pFFA = $this->parse($this->definition(0, self::SESSION, [[253, 4, self::UINT32]]) . $this->data(0, pack('V', 1000)));

        $this->assertSame('Garmin', $pFFA->enumData('manufacturer', 1), 'the library\'s own name is kept');
        $this->assertSame('whoop', $pFFA->enumData('manufacturer', 305));
        $this->assertSame('Forerunner 970', $pFFA->enumData('product', 4565));
        $this->assertSame('unknown', $pFFA->enumData('product', 13), 'APP-2016: single-byte IDs stay unknown, not the SDK\'s name');
        $this->assertSame('Brick', $pFFA->enumData('sub_sport', 80));
        $this->assertSame('Canoeing', $pFFA->enumData('sport', 88));
        $this->assertSame('session_end', $pFFA->enumData('lap_trigger', 7), 'any SDK type');
        $this->assertSame(['interval', 'unknown'], $pFFA->enumData('intensity', [5, 200]));
    }

    public function testManufacturerAndProductAreThoseOfTheCreatorDevice()
    {
        // A paired sensor's device_info first, then the watch's (device_index 0, the creator).
        $pFFA = $this->parse(
            $this->definition(0, self::DEVICE_INFO, [[253, 4, self::UINT32], [0, 1, self::UINT8], [2, 2, self::UINT16], [4, 2, self::UINT16]])
            . $this->data(0, pack('VCvv', 1000, 2, 32, 5))
            . $this->data(0, pack('VCvv', 1000, 0, 1, 4565))
        );

        $this->assertSame('Garmin', $pFFA->manufacturer());
        $this->assertSame('Forerunner 970', $pFFA->product());
    }
}
